import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { ArtifactFeed } from "./ArtifactFeed.js";
import { ModuleVersionInstance } from "./ModuleVersionInstance.js";

export class ArtifactFeedService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Facade.ArtifactFeedService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @returns {Promise<ArtifactFeed[]>}
   */
  static async getArtifactFeedsByProject(token, projectId) {
    try {
      const returnObjectIC = await ArtifactFeedService.type
        .invokeStaticMethod("GetArtifactFeedsByProject", token, projectId)
        .execute();

      await GraftUtils.RegisterType(ArtifactFeed, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * Overload 1:
   * @param {string} token
   * @param {string} projectId
   * @param {string} name
   * @param {string} protocol
   * @param {string} type
   * @param {string} url
   * @returns {Promise<ArtifactFeed>}
   * Overload 2:
   * @param {string} token
   * @param {string} projectId
   * @param {string} name
   * @param {string} protocol
   * @param {string} type
   * @param {string} url
   * @param {import("./index.js").ArtifactFeedAuthentication} authentication
   * @returns {Promise<ArtifactFeed>}
   */
  static async createArtifactFeed(...args) {
    try {
      const returnObjectIC = await (args !== undefined
        ? ArtifactFeedService.type
            .invokeStaticMethod(
              "CreateArtifactFeed",
              ...GraftUtils.ArgsConverter(...args),
            )
            .execute()
        : ArtifactFeedService.type
            .invokeStaticMethod("CreateArtifactFeed")
            .execute());
      await GraftUtils.RegisterType(ArtifactFeed, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} artifactFeedId
   * @param {string} url
   * @returns {Promise<void>}
   */
  static async updateArtifactFeedUrl(token, projectId, artifactFeedId, url) {
    try {
      ArtifactFeedService.type
        .invokeStaticMethod(
          "UpdateArtifactFeedUrl",
          token,
          projectId,
          artifactFeedId,
          url,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} artifactFeedId
   * @param {import("./index.js").ArtifactFeedAuthentication} authentication
   * @returns {Promise<void>}
   */
  static async updateArtifactFeedAuthentication(
    token,
    projectId,
    artifactFeedId,
    authentication,
  ) {
    try {
      ArtifactFeedService.type
        .invokeStaticMethod(
          "UpdateArtifactFeedAuthentication",
          ...GraftUtils.ArgsConverter(
            token,
            projectId,
            artifactFeedId,
            authentication,
          ),
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {ArtifactFeedOrder[]} orders
   * @returns {Promise<void>}
   */
  static async reorderArtifactFeeds(token, projectId, orders) {
    try {
      ArtifactFeedService.type
        .invokeStaticMethod(
          "ReorderArtifactFeeds",
          ...GraftUtils.ArgsConverter(token, projectId, orders),
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * Overload 1:
   * @param {string} projectKey
   * @param {import("./index.js").ModelData} modelData
   * @returns {Promise<void>}
   * Overload 2:
   * @param {string} projectKey
   * @param {number[]} ugmBytes
   * @param {string} runtimeId
   * @param {string} runtimeName
   * @param {string} runtimeVersion
   * @param {string} filter
   * @param {string} filterHash
   * @returns {Promise<void>}
   */
  static async publishLocalModelToFeed(...args) {
    try {
      await (args !== undefined
        ? ArtifactFeedService.type
            .invokeStaticMethod(
              "PublishLocalModelToFeed",
              ...GraftUtils.ArgsConverter(...args),
            )
            .execute()
        : ArtifactFeedService.type
            .invokeStaticMethod("PublishLocalModelToFeed")
            .execute());
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} virtualModuleId
   * @param {string} projectId
   * @returns {Promise<ModuleVersionInstance>}
   */
  static async getVirtualModule(token, virtualModuleId, projectId) {
    try {
      const returnObjectIC = await ArtifactFeedService.type
        .invokeStaticMethod(
          "GetVirtualModule",
          token,
          virtualModuleId,
          projectId,
        )
        .execute();

      await GraftUtils.RegisterType(
        ModuleVersionInstance,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {ModuleVersionInstance} virtualModule
   * @param {string} projectKey
   * @param {string} artifactFeedId
   * @returns {Promise<void>}
   */
  static async reportPublishedModuleToFeed(
    virtualModule,
    projectKey,
    artifactFeedId,
  ) {
    try {
      ArtifactFeedService.type
        .invokeStaticMethod(
          "ReportPublishedModuleToFeed",
          ...GraftUtils.ArgsConverter(
            virtualModule,
            projectKey,
            artifactFeedId,
          ),
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<boolean>}
   */
  static async isHealthy() {
    try {
      const returnObjectIC = await ArtifactFeedService.type
        .invokeStaticMethod("IsHealthy")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
