  /**
   * @param {string} name
   * @param {string} description
   * @param {string} version
   * @param {string} feedProtocol
   * @param {string} feedType
   * @param {string} moduleVersionInstanceId
   */
  constructor(
    name,
    description,
    version,
    feedProtocol,
    feedType,
    moduleVersionInstanceId,
  ) {
    this.#args = [
      name,
      description,
      version,
      feedProtocol,
      feedType,
      moduleVersionInstanceId,
    ];
    if (this.#args?.length === 0) {
      this.#instance = HostedModuleDetails.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : HostedModuleDetails.type.createInstance(...this.#args);
    }
  }
