import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class GatewayFilters {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.Gateways.Dtos.GatewayFilters",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_dateFrom() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("DateFrom")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get dateFrom() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("DateFrom")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_dateTo() {
    {
      const returnObjectIC = this.instance.getInstanceField("DateTo").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get dateTo() {
    {
      const returnObjectIC = this.instance.getInstanceField("DateTo").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string[] | Promise<string[]>}
   */
  get_hostedRuntimes() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("HostedRuntimes")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => result.retrieveArray())
        : returnObjectIC.retrieveArray();
    }
  }
  /**
   * @returns {string[] | Promise<string[]>}
   */
  get hostedRuntimes() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("HostedRuntimes")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => result.retrieveArray())
        : returnObjectIC.retrieveArray();
    }
  }

  /**
   * @returns {string[] | Promise<string[]>}
   */
  get_statuses() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Statuses")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => result.retrieveArray())
        : returnObjectIC.retrieveArray();
    }
  }
  /**
   * @returns {string[] | Promise<string[]>}
   */
  get statuses() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Statuses")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => result.retrieveArray())
        : returnObjectIC.retrieveArray();
    }
  }

  /**
   * @returns {string[] | Promise<string[]>}
   */
  get_hostedModuleNames() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("HostedModuleNames")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => result.retrieveArray())
        : returnObjectIC.retrieveArray();
    }
  }
  /**
   * @returns {string[] | Promise<string[]>}
   */
  get hostedModuleNames() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("HostedModuleNames")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => result.retrieveArray())
        : returnObjectIC.retrieveArray();
    }
  }

  /**
   * @param {string} dateFrom
   * @param {string} dateTo
   * @param {string[]} hostedRuntimes
   * @param {string[]} statuses
   * @param {string[]} hostedModuleNames
   */
  constructor(dateFrom, dateTo, hostedRuntimes, statuses, hostedModuleNames) {
    this.#args = [
      dateFrom,
      dateTo,
      hostedRuntimes,
      statuses,
      hostedModuleNames,
    ];
    if (this.#args?.length === 0) {
      this.#instance = GatewayFilters.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : GatewayFilters.type.createInstance(...this.#args);
    }
  }
}
