import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class ArtifactFeedOrder {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Dtos.ArtifactFeedOrder",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_artifactFeedId() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("ArtifactFeedId")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get artifactFeedId() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("ArtifactFeedId")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {number | Promise<number>}
   */
  get_order() {
    {
      const returnObjectIC = this.instance.getInstanceField("Order").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {number | Promise<number>}
   */
  get order() {
    {
      const returnObjectIC = this.instance.getInstanceField("Order").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @param {string} artifactFeedId
   * @param {number} order
   */
  constructor(artifactFeedId, order) {
    this.#args = [artifactFeedId, order];
    if (this.#args?.length === 0) {
      this.#instance = ArtifactFeedOrder.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : ArtifactFeedOrder.type.createInstance(...this.#args);
    }
  }
}
