import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { RegionalUserData } from "./RegionalUserData.js";

export class RegionalUserService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.RegionalUsers.Facade.RegionalUserService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} token
   * @param {RegionalUserData} userRegionalData
   * @returns {Promise<string>}
   */
  static async addUserRegionalData(token, userRegionalData) {
    try {
      const returnObjectIC = await RegionalUserService.type
        .invokeStaticMethod(
          "AddUserRegionalData",
          ...GraftUtils.ArgsConverter(token, userRegionalData),
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @returns {Promise<RegionalUserData>}
   */
  static async getUserRegionalData(token) {
    try {
      const returnObjectIC = await RegionalUserService.type
        .invokeStaticMethod("GetUserRegionalData", token)
        .execute();

      await GraftUtils.RegisterType(RegionalUserData, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2Mtoken
   * @param {string[]} userIds
   * @param {string} region
   * @returns {Promise<RegionalUserData[]>}
   */
  static async getUserRegionalDataByRegion(m2Mtoken, userIds, region) {
    try {
      const returnObjectIC = await RegionalUserService.type
        .invokeStaticMethod(
          "GetUserRegionalDataByRegion",
          ...GraftUtils.ArgsConverter(m2Mtoken, userIds, region),
        )
        .execute();

      await GraftUtils.RegisterType(RegionalUserData, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2Mtoken
   * @param {string[]} userIds
   * @returns {Promise<RegionalUserData[]>}
   */
  static async getUserRegionalDataByUserIds(m2Mtoken, userIds) {
    try {
      const returnObjectIC = await RegionalUserService.type
        .invokeStaticMethod(
          "GetUserRegionalDataByUserIds",
          ...GraftUtils.ArgsConverter(m2Mtoken, userIds),
        )
        .execute();

      await GraftUtils.RegisterType(RegionalUserData, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string[]} userIds
   * @returns {Promise<RegionalUserData[]>}
   */
  static async getRegionalUsersByUserIds(token, userIds) {
    try {
      const returnObjectIC = await RegionalUserService.type
        .invokeStaticMethod(
          "GetRegionalUsersByUserIds",
          ...GraftUtils.ArgsConverter(token, userIds),
        )
        .execute();

      await GraftUtils.RegisterType(RegionalUserData, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} firstname
   * @param {string} lastname
   * @returns {Promise<void>}
   */
  static async updateUserNames(token, firstname, lastname) {
    try {
      RegionalUserService.type
        .invokeStaticMethod("UpdateUserNames", token, firstname, lastname)
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {number[]} avatar
   * @returns {Promise<void>}
   */
  static async updateUserAvatar(token, avatar) {
    try {
      RegionalUserService.type
        .invokeStaticMethod(
          "UpdateUserAvatar",
          ...GraftUtils.ArgsConverter(token, avatar),
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} userEmail
   * @returns {Promise<void>}
   */
  static async updateUserEmail(token, userEmail) {
    try {
      RegionalUserService.type
        .invokeStaticMethod("UpdateUserEmail", token, userEmail)
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2Mtoken
   * @param {string} email
   * @returns {Promise<RegionalUserData>}
   */
  static async getUserRegionalDataByEmail(m2Mtoken, email) {
    try {
      const returnObjectIC = await RegionalUserService.type
        .invokeStaticMethod("GetUserRegionalDataByEmail", m2Mtoken, email)
        .execute();

      await GraftUtils.RegisterType(RegionalUserData, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<boolean>}
   */
  static async isHealthy() {
    try {
      const returnObjectIC = await RegionalUserService.type
        .invokeStaticMethod("IsHealthy")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
