import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class GraftsFilter {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Dtos.GraftsFilter",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_feedType() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("FeedType")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get feedType() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("FeedType")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_feedProtocol() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("FeedProtocol")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get feedProtocol() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("FeedProtocol")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @param {string} feedType
   * @param {string} feedProtocol
   */
  constructor(feedType, feedProtocol) {
    this.#args = [feedType, feedProtocol];
    if (this.#args?.length === 0) {
      this.#instance = GraftsFilter.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : GraftsFilter.type.createInstance(...this.#args);
    }
  }
}
