import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class UserData {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType("GC.Webportals.Users.Dtos.UserData");
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_userId() {
    {
      const returnObjectIC = this.instance.getInstanceField("UserId").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get userId() {
    {
      const returnObjectIC = this.instance.getInstanceField("UserId").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_emailHash() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("EmailHash")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get emailHash() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("EmailHash")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @param {string} userId
   * @param {string} emailHash
   */
  constructor(userId, emailHash) {
    this.#args = [userId, emailHash];
    if (this.#args?.length === 0) {
      this.#instance = UserData.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : UserData.type.createInstance(...this.#args);
    }
  }
}
