  /**
   * @param {string[]} ugmBase64
   * @param {string} runtimeId
   * @param {string} runtimeName
   * @param {string} runtimeVersion
   * @param {string} filter
   * @param {string} filterHash
   */
  constructor(
    ugmBase64,
    runtimeId,
    runtimeName,
    runtimeVersion,
    filter,
    filterHash,
  ) {
    this.#args = [
      ugmBase64,
      runtimeId,
      runtimeName,
      runtimeVersion,
      filter,
      filterHash,
    ];
    if (this.#args?.length === 0) {
      this.#instance = ModelData.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : ModelData.type.createInstance(...this.#args);
    }
  }
