import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { UserRegionalIdentity } from "./UserRegionalIdentity.js";

export class UserService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType("GC.Webportals.Users.Facade.UserService");
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} apiToken
   * @param {string} email
   * @param {string} userId
   * @param {string} correlationId
   * @returns {Promise<string>}
   */
  static async createOrResolveUser(apiToken, email, userId, correlationId) {
    try {
      const returnObjectIC = await UserService.type
        .invokeStaticMethod(
          "CreateOrResolveUser",
          apiToken,
          email,
          userId,
          correlationId,
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} regionString
   * @param {string} lastUsedWorkspaceId
   * @returns {Promise<string>}
   */
  static async addUserRegionalIdentity(
    token,
    regionString,
    lastUsedWorkspaceId,
  ) {
    try {
      const returnObjectIC = await UserService.type
        .invokeStaticMethod(
          "AddUserRegionalIdentity",
          token,
          regionString,
          lastUsedWorkspaceId,
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @returns {Promise<UserRegionalIdentity[]>}
   */
  static async getUserIdentities(token) {
    try {
      const returnObjectIC = await UserService.type
        .invokeStaticMethod("GetUserIdentities", token)
        .execute();

      await GraftUtils.RegisterType(UserRegionalIdentity, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @returns {Promise<void>}
   */
  static async deleteUser(token) {
    try {
      UserService.type.invokeStaticMethod("DeleteUser", token).execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} emailHash
   * @returns {Promise<string>}
   */
  static async resolveUserIdByVerifiedEmailHash(m2MToken, emailHash) {
    try {
      const returnObjectIC = await UserService.type
        .invokeStaticMethod(
          "ResolveUserIdByVerifiedEmailHash",
          m2MToken,
          emailHash,
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @returns {Promise<boolean>}
   */
  static async isUserRegistered(token) {
    try {
      const returnObjectIC = await UserService.type
        .invokeStaticMethod("IsUserRegistered", token)
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} workspaceId
   * @returns {Promise<void>}
   */
  static async updateWorkspaceContext(token, workspaceId) {
    try {
      UserService.type
        .invokeStaticMethod("UpdateWorkspaceContext", token, workspaceId)
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<boolean>}
   */
  static async isHealthy() {
    try {
      const returnObjectIC = await UserService.type
        .invokeStaticMethod("IsHealthy")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
