import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { ArtifactFeed } from "./ArtifactFeed.js";
import { UpstreamFeed } from "./UpstreamFeed.js";

export class PublicFeedService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Facade.PublicFeedService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @returns {Promise<ArtifactFeed[]>}
   */
  static async getPublicFeedsByProject(token, projectId) {
    try {
      const returnObjectIC = await PublicFeedService.type
        .invokeStaticMethod("GetPublicFeedsByProject", token, projectId)
        .execute();

      await GraftUtils.RegisterType(ArtifactFeed, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} name
   * @param {string} protocol
   * @param {string} url
   * @returns {Promise<ArtifactFeed>}
   */
  static async createPublicFeed(token, projectId, name, protocol, url) {
    try {
      const returnObjectIC = await PublicFeedService.type
        .invokeStaticMethod(
          "CreatePublicFeed",
          token,
          projectId,
          name,
          protocol,
          url,
        )
        .execute();

      await GraftUtils.RegisterType(ArtifactFeed, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} artifactFeedId
   * @param {string} url
   * @returns {Promise<void>}
   */
  static async updatePublicFeedUrl(token, projectId, artifactFeedId, url) {
    try {
      PublicFeedService.type
        .invokeStaticMethod(
          "UpdatePublicFeedUrl",
          token,
          projectId,
          artifactFeedId,
          url,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} artifactFeedId
   * @returns {Promise<void>}
   */
  static async deletePublicFeed(token, projectId, artifactFeedId) {
    try {
      PublicFeedService.type
        .invokeStaticMethod(
          "DeletePublicFeed",
          token,
          projectId,
          artifactFeedId,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} projectId
   * @returns {Promise<boolean>}
   */
  static async configureDefaultPublicFeeds(projectId) {
    try {
      const returnObjectIC = await PublicFeedService.type
        .invokeStaticMethod("ConfigureDefaultPublicFeeds", projectId)
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} projectId
   * @returns {Promise<UpstreamFeed[]>}
   */
  static async getUpstreamFeedsForProject(m2MToken, projectId) {
    try {
      const returnObjectIC = await PublicFeedService.type
        .invokeStaticMethod("GetUpstreamFeedsForProject", m2MToken, projectId)
        .execute();

      await GraftUtils.RegisterType(UpstreamFeed, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
