import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { ArtifactFeed } from "./ArtifactFeed.js";

export class PrivateFeedService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Facade.PrivateFeedService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @returns {Promise<ArtifactFeed[]>}
   */
  static async getPrivateFeedsByProject(token, projectId) {
    try {
      const returnObjectIC = await PrivateFeedService.type
        .invokeStaticMethod("GetPrivateFeedsByProject", token, projectId)
        .execute();

      await GraftUtils.RegisterType(ArtifactFeed, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} name
   * @param {string} protocol
   * @param {string} url
   * @param {import("./index.js").ArtifactFeedAuthentication} authentication
   * @returns {Promise<ArtifactFeed>}
   */
  static async createPrivateFeed(
    token,
    projectId,
    name,
    protocol,
    url,
    authentication,
  ) {
    try {
      const returnObjectIC = await PrivateFeedService.type
        .invokeStaticMethod(
          "CreatePrivateFeed",
          ...GraftUtils.ArgsConverter(
            token,
            projectId,
            name,
            protocol,
            url,
            authentication,
          ),
        )
        .execute();

      await GraftUtils.RegisterType(ArtifactFeed, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} artifactFeedId
   * @param {string} url
   * @returns {Promise<void>}
   */
  static async updatePrivateFeedUrl(token, projectId, artifactFeedId, url) {
    try {
      PrivateFeedService.type
        .invokeStaticMethod(
          "UpdatePrivateFeedUrl",
          token,
          projectId,
          artifactFeedId,
          url,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} artifactFeedId
   * @param {import("./index.js").ArtifactFeedAuthentication} authentication
   * @returns {Promise<void>}
   */
  static async updatePrivateFeedAuthentication(
    token,
    projectId,
    artifactFeedId,
    authentication,
  ) {
    try {
      PrivateFeedService.type
        .invokeStaticMethod(
          "UpdatePrivateFeedAuthentication",
          ...GraftUtils.ArgsConverter(
            token,
            projectId,
            artifactFeedId,
            authentication,
          ),
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} artifactFeedId
   * @returns {Promise<void>}
   */
  static async deletePrivateFeed(token, projectId, artifactFeedId) {
    try {
      PrivateFeedService.type
        .invokeStaticMethod(
          "DeletePrivateFeed",
          token,
          projectId,
          artifactFeedId,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
