// @ts-check
// @ts-ignore - ComplexTypeResolver may not be in type definitions
import { ComplexTypeResolver } from "hypertube-nodejs-sdk";

const complexTypeResolver = new ComplexTypeResolver();

class GraftUtils {
  /**
   * Checks if the given value represents an invocation context.
   * Uses method/property detection instead of constructor names to work with minified code.
   * @param {any} x - The value to check
   * @returns {boolean} True if the value is an invocation context, false otherwise
   */
  static isInvocationContext(x) {
    if (!x || x === null || typeof x !== "object") {
      return false;
    }
    try {
      if (x?.instance) {
        return !!Object.getPrototypeOf(x?.instance)?.invokeStaticMethod;
      }
      return !!Object.getPrototypeOf(x)?.invokeStaticMethod;
    } catch {
      return false;
    }
  }

  /**
   * @param {any} x - The value to check for thenable interface
   * @returns {boolean} True if the value has a callable `then` method, false otherwise
   */
  static isThenable(x) {
    return x != null && typeof x?.then === "function";
  }

  /**
   * Gets the value from an invocation context or promise.
   * @param {any} invocationContext - The value to get
   * @returns {Promise<any>} The resolved value
   */
  static getValue(invocationContext) {
    return GraftUtils.isThenable(invocationContext)
      ? invocationContext.then((ic) => ic.getValue())
      : invocationContext.getValue();
  }

  /**
   * Wraps an exception object for consistent error handling.
   * @param {Error | any} ex - The exception to wrap
   * @returns {Error | any} The wrapped exception (currently returns the input unchanged)
   */
  static ExceptionWrapper(ex) {
    return ex;
  }

  /**
   * Converts and normalizes arguments for method invocation.
   * Recursively processes nested arrays to find and convert InvocationContext objects.
   * @param {...any} args - The arguments to convert
   * @returns {any[]} The converted arguments array
   */
  static ArgsConverter(...args) {
    const convert = (arg) => {
      if (GraftUtils.isInvocationContext(arg)) {
        return arg.instance !== undefined ? arg.instance : arg;
      }
      if (Array.isArray(arg)) {
        return arg.map(convert);
      }
      return arg;
    };
    return args.map(convert);
  }

  /**
   * Registers a type mapping for complex type conversion.
   * This is the JavaScript equivalent of ComplexTypeResolver.Instance.Register.
   * @param {new (...args: any[]) => any} type - The target class to register
   * @param {any | Promise<any>} invocationContext
   * @returns {Promise<void> | void}
   */
  static RegisterType(
    type,
    invocationContext,
    withTryUnderlyingArrayType = false,
  ) {
    if (!type) {
      return;
    }

    const registerContext = (context) => {
      if (!GraftUtils.isInvocationContext(context)) {
        return;
      }

      const registerResolvedType = (resultType) => {
        const resolvedType = withTryUnderlyingArrayType
          ? GraftUtils.TryGetUnderlyingArrayType(resultType) || resultType
          : resultType;

        if (resolvedType) {
          complexTypeResolver.register(resolvedType, type, [context]);
        }
      };

      const resultType = context.getResultType();
      if (GraftUtils.isThenable(resultType)) {
        return resultType.then(registerResolvedType);
      }
      return registerResolvedType(resultType);
    };

    if (GraftUtils.isThenable(invocationContext)) {
      return invocationContext.then((context) => registerContext(context));
    }
    return registerContext(invocationContext);
  }

  /**
   * Converts and processes method invocation results.
   * For complex types (InvocationContext), uses Hypertube's ComplexTypeResolver to convert.
   * @param {any} result - The result to convert
   * @returns {any} The converted result
   */
  static ConvertResult(result) {
    if (GraftUtils.isInvocationContext(result)) {
      return complexTypeResolver.convertResult(result);
    }
    return result;
  }

  static TryGetUnderlyingArrayType(resultType) {
    return ComplexTypeResolver.tryGetUnderlyingArrayType(resultType);
  }
}

export { GraftUtils };
