import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { ModuleVersionInstance } from "./ModuleVersionInstance.js";
import { PublishResult } from "./PublishResult.js";

export class VirtualFeedService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Facade.VirtualFeedService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {ModuleVersionInstance[]} moduleVersionInstances
   * @param {string} gatewayName
   * @returns {Promise<PublishResult[]>}
   */
  static async getGatewayDetails(moduleVersionInstances, gatewayName) {
    try {
      const returnObjectIC = await VirtualFeedService.type
        .invokeStaticMethod(
          "GetGatewayDetails",
          ...GraftUtils.ArgsConverter(moduleVersionInstances, gatewayName),
        )
        .execute();

      await GraftUtils.RegisterType(PublishResult, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {ModuleVersionInstance[]} moduleVersionInstances
   * @param {string} credentials
   * @param {string} gatewayName
   * @returns {Promise<PublishResult[]>}
   */
  static async publishModulesToVirtualFeed(
    moduleVersionInstances,
    credentials,
    gatewayName,
  ) {
    try {
      const returnObjectIC = await VirtualFeedService.type
        .invokeStaticMethod(
          "PublishModulesToVirtualFeed",
          ...GraftUtils.ArgsConverter(
            moduleVersionInstances,
            credentials,
            gatewayName,
          ),
        )
        .execute();

      await GraftUtils.RegisterType(PublishResult, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * Overload 1:
   * @param {string} projectKey
   * @param {number[]} ugmBytes
   * @param {string} runtimeId
   * @param {string} runtimeName
   * @param {string} runtimeVersion
   * @param {string} filter
   * @param {string} filterHash
   * @returns {Promise<void>}
   * Overload 2:
   * @param {string} projectKey
   * @param {import("./index.js").ModelData} modelData
   * @returns {Promise<void>}
   */
  static async publishLocalModelToFeed(...args) {
    try {
      await (args !== undefined
        ? VirtualFeedService.type
            .invokeStaticMethod(
              "PublishLocalModelToFeed",
              ...GraftUtils.ArgsConverter(...args),
            )
            .execute()
        : VirtualFeedService.type
            .invokeStaticMethod("PublishLocalModelToFeed")
            .execute());
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} moduleVersionInstanceId
   * @param {string} projectId
   * @returns {Promise<ModuleVersionInstance>}
   */
  static async getModuleVersionInstance(
    token,
    moduleVersionInstanceId,
    projectId,
  ) {
    try {
      const returnObjectIC = await VirtualFeedService.type
        .invokeStaticMethod(
          "GetModuleVersionInstance",
          token,
          moduleVersionInstanceId,
          projectId,
        )
        .execute();

      await GraftUtils.RegisterType(
        ModuleVersionInstance,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {ModuleVersionInstance} moduleVersionInstance
   * @param {string} projectKey
   * @param {string} artifactFeedId
   * @returns {Promise<void>}
   */
  static async reportPublishedModuleToFeed(
    moduleVersionInstance,
    projectKey,
    artifactFeedId,
  ) {
    try {
      VirtualFeedService.type
        .invokeStaticMethod(
          "ReportPublishedModuleToFeed",
          ...GraftUtils.ArgsConverter(
            moduleVersionInstance,
            projectKey,
            artifactFeedId,
          ),
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string[]} moduleVersionInstanceIds
   * @returns {Promise<ModuleVersionInstance[]>}
   */
  static async getModuleVersionInstances(
    token,
    projectId,
    moduleVersionInstanceIds,
  ) {
    try {
      const returnObjectIC = await VirtualFeedService.type
        .invokeStaticMethod(
          "GetModuleVersionInstances",
          ...GraftUtils.ArgsConverter(
            token,
            projectId,
            moduleVersionInstanceIds,
          ),
        )
        .execute();

      await GraftUtils.RegisterType(
        ModuleVersionInstance,
        returnObjectIC,
        true,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<boolean>}
   */
  static async isHealthy() {
    try {
      const returnObjectIC = await VirtualFeedService.type
        .invokeStaticMethod("IsHealthy")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
