import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { Graft } from "./Graft.js";

export class GraftService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Facade.GraftService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} m2MToken
   * @param {string} projectId
   * @param {string} nameSpace
   * @param {string} name
   * @param {string} version
   * @param {string} feedProtocol
   * @returns {Promise<boolean>}
   */
  static async reportGraftDownload(
    m2MToken,
    projectId,
    nameSpace,
    name,
    version,
    feedProtocol,
  ) {
    try {
      const returnObjectIC = await GraftService.type
        .invokeStaticMethod(
          "ReportGraftDownload",
          m2MToken,
          projectId,
          nameSpace,
          name,
          version,
          feedProtocol,
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {import("./index.js").GraftsFilter} filter
   * @returns {Promise<Graft[]>}
   */
  static async getGraftsByProjectId(token, projectId, filter) {
    try {
      const returnObjectIC = await GraftService.type
        .invokeStaticMethod(
          "GetGraftsByProjectId",
          ...GraftUtils.ArgsConverter(token, projectId, filter),
        )
        .execute();

      await GraftUtils.RegisterType(Graft, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
