import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { Gateway } from "./Gateway.js";

export class GatewayService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.Gateways.Facade.GatewayService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} projectKey
   * @param {string} username
   * @param {string} gatewayName
   * @param {HostedRuntime[]} hostedRuntimes
   * @param {string[]} moduleVersionInstanceIds
   * @returns {Promise<string>}
   */
  static async addOrUpdateGateway(
    projectKey,
    username,
    gatewayName,
    hostedRuntimes,
    moduleVersionInstanceIds,
  ) {
    try {
      const returnObjectIC = await GatewayService.type
        .invokeStaticMethod(
          "AddOrUpdateGateway",
          ...GraftUtils.ArgsConverter(
            projectKey,
            username,
            gatewayName,
            hostedRuntimes,
            moduleVersionInstanceIds,
          ),
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} name
   * @returns {Promise<string>}
   */
  static async addNewGateway(token, projectId, name) {
    try {
      const returnObjectIC = await GatewayService.type
        .invokeStaticMethod("AddNewGateway", token, projectId, name)
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * Overload 1:
   * @param {string} gatewayKey
   * @param {HostedRuntime[]} hostedRuntimes
   * @param {string[]} moduleVersionInstanceIds
   * @param {number} typesExposed
   * @param {number} methodExposed
   * @param {number} fieldsExposed
   * @returns {Promise<string>}
   * Overload 2:
   * @param {import("./index.js").HostedRuntime} hostedRuntime
   * @param {HostedModuleDetails[]} hostedModules
   * @param {string} gatewayKey
   * @returns {Promise<void>}
   */
  static async updateGateway(...args) {
    try {
      const returnObjectIC = await (args !== undefined
        ? GatewayService.type
            .invokeStaticMethod(
              "UpdateGateway",
              ...GraftUtils.ArgsConverter(...args),
            )
            .execute()
        : GatewayService.type.invokeStaticMethod("UpdateGateway").execute());
      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} dateFrom
   * @param {string} dateTo
   * @returns {Promise<Gateway[]>}
   */
  static async getGateways(token, projectId, dateFrom, dateTo) {
    try {
      const returnObjectIC = await GatewayService.type
        .invokeStaticMethod("GetGateways", token, projectId, dateFrom, dateTo)
        .execute();

      await GraftUtils.RegisterType(Gateway, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} credentials
   * @returns {Promise<boolean>}
   */
  static async didGatewayReportAnyUgm(credentials) {
    try {
      const returnObjectIC = await GatewayService.type
        .invokeStaticMethod("DidGatewayReportAnyUgm", credentials)
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} gatewayName
   * @returns {Promise<boolean>}
   */
  static async isGatewayReported(token, projectId, gatewayName) {
    try {
      const returnObjectIC = await GatewayService.type
        .invokeStaticMethod("IsGatewayReported", token, projectId, gatewayName)
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} credentials
   * @param {string} gatewayName
   * @param {string} ipAddress
   * @param {string} hostname
   * @returns {Promise<void>}
   */
  static async reportGatewayLocation(
    credentials,
    gatewayName,
    ipAddress,
    hostname,
  ) {
    try {
      GatewayService.type
        .invokeStaticMethod(
          "ReportGatewayLocation",
          credentials,
          gatewayName,
          ipAddress,
          hostname,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} gatewayId
   * @param {boolean} isFavourite
   * @returns {Promise<void>}
   */
  static async setIsFavouriteGateway(token, gatewayId, isFavourite) {
    try {
      GatewayService.type
        .invokeStaticMethod(
          "SetIsFavouriteGateway",
          token,
          gatewayId,
          isFavourite,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<boolean>}
   */
  static async isHealthy() {
    try {
      const returnObjectIC = await GatewayService.type
        .invokeStaticMethod("IsHealthy")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
