import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class HostedRuntime {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.Gateways.Dtos.HostedRuntime",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_hostedRuntimeId() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("HostedRuntimeId")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get hostedRuntimeId() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("HostedRuntimeId")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_name() {
    {
      const returnObjectIC = this.instance.getInstanceField("Name").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get name() {
    {
      const returnObjectIC = this.instance.getInstanceField("Name").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_version() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Version")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get version() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Version")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * Overload 1:
   * @param {string} hostedRuntimeId
   * @param {string} name
   * @param {string} version
   * Overload 2:
   * @param {string} name
   * @param {string} version
   */
  constructor(...args) {
    this.#args = args;
    if (this.#args?.length === 0) {
      this.#instance = HostedRuntime.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : HostedRuntime.type.createInstance(...this.#args);
    }
  }
}
