import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { AuthorizedArtifactFeedsResult } from "./AuthorizedArtifactFeedsResult.js";

export class ArtifactFeedAuthorizationService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Facade.ArtifactFeedAuthorizationService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} m2MToken
   * @param {string} credentials
   * @returns {Promise<AuthorizedArtifactFeedsResult>}
   */
  static async getAuthorizedArtifactFeeds(m2MToken, credentials) {
    try {
      const returnObjectIC = await ArtifactFeedAuthorizationService.type
        .invokeStaticMethod("GetAuthorizedArtifactFeeds", m2MToken, credentials)
        .execute();

      await GraftUtils.RegisterType(
        AuthorizedArtifactFeedsResult,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
