import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class ArtifactFeedAuthentication {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Dtos.ArtifactFeedAuthentication",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_artifactFeedAuthenticationId() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("ArtifactFeedAuthenticationId")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get artifactFeedAuthenticationId() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("ArtifactFeedAuthenticationId")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_feedAuthenticationMethod() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("FeedAuthenticationMethod")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get feedAuthenticationMethod() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("FeedAuthenticationMethod")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_credentials() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Credentials")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get credentials() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Credentials")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @param {string} feedAuthenticationMethod
   * @param {string} credentials
   */
  constructor(feedAuthenticationMethod, credentials) {
    this.#args = [feedAuthenticationMethod, credentials];
    if (this.#args?.length === 0) {
      this.#instance = ArtifactFeedAuthentication.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : ArtifactFeedAuthentication.type.createInstance(...this.#args);
    }
  }
}
