import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { AuthorizedArtifactFeed } from "./AuthorizedArtifactFeed.js";

export class AuthorizedArtifactFeedsResult {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Dtos.AuthorizedArtifactFeedsResult",
    );
  }

  get instance() {
    return this.#instance;
  }
  constructor(...args) {
    this.#args = args;
    if (this.#args?.length === 0) {
      this.#instance = AuthorizedArtifactFeedsResult.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : AuthorizedArtifactFeedsResult.type.createInstance(...this.#args);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_projectId() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("ProjectId")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get projectId() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("ProjectId")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {AuthorizedArtifactFeed[] | Promise<AuthorizedArtifactFeed[]>}
   */
  get_feeds() {
    {
      try {
        const returnObjectIC = this.instance
          .getInstanceField("Feeds")
          .execute();
        if (GraftUtils.isThenable(returnObjectIC)) {
          return returnObjectIC.then((result) =>
            GraftUtils.RegisterType(AuthorizedArtifactFeed, result, true).then(
              () => GraftUtils.ConvertResult(result),
            ),
          );
        } else {
          GraftUtils.RegisterType(AuthorizedArtifactFeed, returnObjectIC, true);
          return GraftUtils.ConvertResult(returnObjectIC);
        }
      } catch (ex) {
        throw GraftUtils.ExceptionWrapper(ex);
      }
    }
  }
  /**
   * @returns {AuthorizedArtifactFeed[] | Promise<AuthorizedArtifactFeed[]>}
   */
  get feeds() {
    {
      try {
        const returnObjectIC = this.instance
          .getInstanceField("Feeds")
          .execute();
        if (GraftUtils.isThenable(returnObjectIC)) {
          return returnObjectIC.then((result) =>
            GraftUtils.RegisterType(AuthorizedArtifactFeed, result, true).then(
              () => GraftUtils.ConvertResult(result),
            ),
          );
        } else {
          GraftUtils.RegisterType(AuthorizedArtifactFeed, returnObjectIC, true);
          return GraftUtils.ConvertResult(returnObjectIC);
        }
      } catch (ex) {
        throw GraftUtils.ExceptionWrapper(ex);
      }
    }
  }
}
