import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class Runtime {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.ArtifactFeeds.Dtos.Runtime",
    );
  }

  get instance() {
    return this.#instance;
  }
  constructor(...args) {
    this.#args = args;
    if (this.#args?.length === 0) {
      this.#instance = Runtime.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : Runtime.type.createInstance(...this.#args);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_runtimeId() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("RuntimeId")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get runtimeId() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("RuntimeId")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_name() {
    {
      const returnObjectIC = this.instance.getInstanceField("Name").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get name() {
    {
      const returnObjectIC = this.instance.getInstanceField("Name").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_version() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Version")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get version() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Version")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
}
